@@ -0,0 +1,45 @@
+/**
+ * Sanitize an SVG document to prevent DOM-based XSS.
+ * Removes <script> tags and event handler attributes (e.g., onload, onclick).
+ * @param {Document} doc The parsed SVG document.
+ * @return {string} The serialized, sanitized SVG string.
+ */
+const sanitizeSvg = function (doc) {
+    // Remove <script> elements.
+    const scripts = doc.querySelectorAll('script');
+    for (let i = 0; i < scripts.length; i++) {
+        scripts[i].parentNode.removeChild(scripts[i]);
+    }
+
+    // Remove event handler attributes from all elements.
+    const allElements = doc.querySelectorAll('*');
+    for (let i = 0; i < allElements.length; i++) {
+        const el = allElements[i];
+        const attrs = el.attributes;
+        for (let j = 0; j < attrs.length; j++) {
+            const attrName = attrs[j].name;
+            // Remove attributes that start with 'on' (e.g., onload, onclick).
+            if (attrName.toLowerCase().startsWith('on')) {
+                el.removeAttribute(attrName);
+            }
+            // Remove javascript: URLs from href and xlink:href attributes.
+            if (attrName === 'href' || attrName === 'xlink:href') {
+                const attrValue = attrs[j].value;
+                if (attrValue.trim().toLowerCase().startsWith('javascript:')) {
+                    el.removeAttribute(attrName);
+                }
+            }
+        }
+    }
+
+    // Serialize the sanitized document back to a string.
+    const serializer = new XMLSerializer();
+    return serializer.serializeToString(doc);
+};
+
+module.exports = sanitizeSvg;

