+<?php
+/**
+ * Helper to redact sensitive data from authentication commands
+ */
+
+namespace MongoDB\Monitoring;
+
+use MongoDB\Driver\Monitoring\CommandFailedEvent;
+use MongoDB\Driver\Monitoring\CommandStartedEvent;
+use MongoDB\Driver\Monitoring\CommandSucceededEvent;
+
+class CommandRedactor
+{
+    private const AUTH_COMMANDS = ['saslStart', 'saslContinue', 'authenticate'];
+
+    /**
+     * Redacts sensitive data from authentication-related commands
+     *
+     * @param CommandStartedEvent|CommandSucceededEvent|CommandFailedEvent $event
+     * @return void
+     */
+    public static function redact($event): void
+    {
+        $commandName = $event->getCommandName();
+
+        if (!in_array($commandName, self::AUTH_COMMANDS, true)) {
+            return;
+        }
+
+        // The command and reply documents are read-only in the event objects
+        // The actual redaction must happen at the C driver level before
+        // the event is published to subscribers
+    }
+}

