+// Safe regex validation to prevent ReDoS attacks
+// Based on heuristics from safe-regex and dfa-regex libraries
+
+const MAX_PATTERN_LENGTH = 1000
+
+// Detect potentially catastrophic patterns:
+// - Nested quantifiers: (a+)+, (a*)*, (a?)+
+// - Overlapping alternation with quantifiers: (a|a)*, (a|ab)*
+// - Large counted quantifiers: a{10,}
+const DANGEROUS_PATTERNS = [
+  /\(([^()]*[+*?][^()]*)\)[+*?]/, // nested quantifiers
+  /\(([^()]*\|[^()]*)\)[+*?]/,    // alternation with quantifier
+  /\{(\d+),(\d*)\}/,              // large counted quantifiers (checked separately)
+]
+
+export function safeRegex(pattern: string): boolean {
+  if (typeof pattern !== "string") {
+    return true // non-string handled elsewhere
+  }
+  
+  // Length check
+  if (pattern.length > MAX_PATTERN_LENGTH) {
+    return false
+  }
+  
+  // Check for large counted quantifiers
+  const countedMatch = pattern.match(/\{(\d+),(\d*)\}/)
+  if (countedMatch) {
+    const min = parseInt(countedMatch[1], 10)
+    const max = countedMatch[2] ? parseInt(countedMatch[2], 10) : Infinity
+    if (min > 100 || max > 1000) {
+      return false
+    }
+  }
+  
+  // Check dangerous patterns
+  for (const dangerous of DANGEROUS_PATTERNS) {
+    if (dangerous.test(pattern)) {
+      return false
+    }
+  }
+  
+  return true
+}

